exercises.starter:
def diesel_efficiency(r, rc, gamma=1.4):
    """Ideal Diesel-cycle efficiency; the Otto value when rc is (almost) 1."""
    return 1 - r ** (1 - gamma)

exercises.reference:
def diesel_efficiency(r, rc, gamma=1.4):
    otto = 1 - r ** (1 - gamma)
    if abs(rc - 1.0) < 1e-6:
        return otto                      # limit of (rc^g - 1) / (g (rc - 1)) as rc -> 1 is 1
    factor = (rc ** gamma - 1) / (gamma * (rc - 1))
    return 1 - r ** (1 - gamma) * factor
